  "operations": [
    {
      "op": "set_repair_policy",
      "component": "repair_policy",
      "actions": ["reroute", "move_bottleneck_service", "bounded_backtrack"]
    }
  ],
  "rationale": "Add move_bottleneck_service to repair policy to potentially reduce latency by relocating bottleneck services, addressing QoS constraint.",
  "version": "1.0"
}

{
  "operations": [
    {
      "op": "set_weight",
      "component": "node_score",
      "feature": "dependency_latency",
      "weight": -0.5
    }
  ],
  "rationale": "Increase negative weight on dependency_latency to discourage placements with high predecessor communication latency, potentially reducing E2E latency.",
  "version": "1.0"
}

{
  "operations": [
    {
      "op": "add_term",
      "component": "node_score",
      "feature": "migration_penalty",
      "weight": -1.0
    }
  ],
  "rationale": "Add migration_penalty with negative weight to node_score to discourage migrations, addressing the migration budget constraint violation.",
  "version": "1.0"
}
